nta.declaration:
// Place global declarations here.
const int N = 5; // number of devices
const int G = 2; // number of gateways

typedef int[0,N-1] device_id;
typedef int[0,G-1] gateway_id;

urgent broadcast chan submit[G][N];

broadcast chan forward[N]; // doesn't need to be urgent

// Maximum value stored by the counters.
// Once this value is reached, the counter stops increasing.
const int CMAX = 100; // ΙΝΤ_ΜΑΧ: 32767

int[0, CMAX] completed[N]; // number of tasks completed (processed by the cloud) for each device

int[0, CMAX] submitted[N]; // number of tasks generated and submitted to the cloud, by each device.. is this incremented if the cloud drops them? no

int[0, CMAX] generated[N]; // number of tasks generated by each device. incremented at device upon generation

int[0, CMAX] forwarded[N]; // if it's NOT dropped by the gateway, it counts are forwarded

// dropped tasks
// at the gateway: generated - forwarded
// at the cloud: forwarded - submitted
// what about completed? all submitted will eventually be completed but we're looking at model behavior at all times

// Tasks dropped by a gateway:
// generated[i] - forwarded[i]
//
// Tasks dropped by the cloud:
// forwarded[i] - submitted[i]
//
// Tasks accepted by the cloud but not yet completed:
// submitted[i] - completed[i]
//
// Total dropped before completion:
// generated[i] - submitted[i]

void increment(int[0, CMAX] &counter)
{
    if (counter < CMAX)
        counter++;
}

template.declaration:
device_id current; // current device

clock t;

// Queue functions
const int QMAX = 3; // queue size (capacity)
device_id list[QMAX];
int[0,QMAX] len = 0; // initialize length

// Put an element at the end of the queue
void enqueue(device_id element)
{
        list[len++] = element;
}

// Remove the front element of the queue
void dequeue()
{
        int i = 0;
        len -= 1;
        while (i < len)
        {
                list[i] = list[i + 1];
                i++;
        }
        list[i] = 0;
}

// Returns the front element of the queue
device_id front()
{
   return list[0];
}

// Enqueue if there's space, otherwise drop
void accept_or_drop(device_id i)
{
    if (len < QMAX)
    {
        enqueue(i);
    }
}

device_id current; // current device

clock t;

// Queue functions
const int QMAX = 5; // queue size (capacity)
device_id list[QMAX];
int[0,QMAX] len = 0; // initialize length

// Put an element at the end of the queue
void enqueue(device_id element)
{
        list[len++] = element;
}

// Remove the front element of the queue
void dequeue()
{
        int i = 0;
        len -= 1;
        while (i < len)
        {
                list[i] = list[i + 1];
                i++;
        }
        list[i] = 0;
}

// Returns the front element of the queue
device_id front()
{
   return list[0];
}

// Enqueue if there's space, otherwise drop
void accept_or_drop(device_id i)
{
    if (len < QMAX)
    {
        enqueue(i);
        increment(submitted[i]);
    }
}
